; stale.asm -- chapter 43: a touch believed twice
; generated by gen43.py
        INCLUDE "msx.inc"
        OUTPUT "stale.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
stat    EQU VARS                ; the status isr read: F, 5S, C, a sprite's number
ticks   EQU VARS + 1            ; frames counted by isr, two bytes
seed    EQU VARS + 3            ; random's state, two bytes (chapter 41)
state   EQU VARS + 5            ; TITLE, PLAY, HIT or OVER
left    EQU VARS + 6            ; the frames left of HIT or of OVER
lives   EQU VARS + 7
gems    EQU VARS + 8            ; the gems of the round still lying
last    EQU VARS + 9            ; ticks' low byte, when the play last counted
held    EQU VARS + 10           ; the keys and the stick: a 0 for each held
stale   EQU VARS + 11           ; frames whose C play1 does not believe
shownl  EQU VARS + 12           ; the lives on the status line
queued  EQU VARS + 13           ; the names queued for the sends
queue   EQU VARS + $10          ; 16 names: the VRAM address, then the name
copy    EQU VARS + $40          ; the sprites' attributes: Y, X, pattern, colour
runner  EQU copy                ; the runner's Y and X
faces   EQU copy + 4            ; and the faces', four each
steps   EQU VARS + $60          ; each face's step, -2 to 2
names   EQU $C400               ; the copy of the 768 names
score   EQU $C700               ; three BCD bytes (chapter 40)
hi      EQU score + 3           ; the best, three more
shown   EQU score + $100        ; the six bytes last sent, a page on
SAT     EQU $1B00               ; the sprites' attributes
SPAT    EQU $3800               ; and their patterns
TITLE   EQU 0                   ; the states
PLAY    EQU 1
HIT     EQU 2
OVER    EQU 3
PAPER   EQU 0                   ; the tiles' names
BRICK   EQU 1
ALLEY   EQU 2
GEM     EQU 3
DIGIT0  EQU $30                 ; '0'
X_MIN   EQU 8                   ; a face's X: X_MIN to X_MAX
X_MAX   EQU 232
HOME_X  EQU 120                 ; the runner's home
HOME_Y  EQU 23
GEMS    EQU 8                   ; gems a round
LIVES   EQU 3
HOLD    EQU 50                  ; frames held still at a touch
WAITS   EQU 150                 ; frames of GAME OVER
POINTS  EQU $10                 ; a gem's, two BCD digits
SCORE_AT EQU $1800 + 7           ; row 0: the score's first digit
LIVES_AT EQU $1800 + 20           ; the lives
HI_AT   EQU $1800 + 26             ; and the best's first digit
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; WHERE IT BREAKS. game.asm believing C in the first frame of the play
; after the runner is put home again.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $01          ; border black
        VRAM_WRITE SAT          ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        ld hl, VARS             ; the variables' page, all 0: ticks,
        ld de, VARS + 1         ; the lives, the queue, stale and the rest
        ld bc, 255
        ld (hl), 0
        ldir
        VRAM_WRITE $0000        ; the four tiles' shapes
        ld hl, tiles
        ld bc, 32 << 8 | VDP_DATA
        otir
        VRAM_WRITE $0100        ; chapter 30's characters, codes 32 to 127
        ld hl, font
        ld b, 3                 ; three runs of 256 bytes
.font:  push bc
        ld b, 0
        otir
        pop bc
        djnz .font
        VRAM_WRITE $2000        ; the tiles' colours
        ld hl, tcols
        ld b, 32
        otir
        VRAM_WRITE $2100        ; the characters', black on white
        ld bc, 768
.fc:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .fc
        VRAM_WRITE SPAT         ; the runner, patterns 0 to 3, and a face, 4 to 7
        ld hl, sprites
        ld bc, 64 << 8 | VDP_DATA
        otir
        ld hl, nums             ; score 000000 and the best at the start,
        ld de, score
        ld bc, 6
        ldir
        ld hl, nums             ; as if on the screen: the title shows neither
        ld de, shown
        ld bc, 6
        ldir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld a, TITLE
        call go                 ; the first state: title0 ends with EI
        di
        in a, (VDP_CTRL)        ; no signal left over (chapter 39)
        VDP_REG 1, $E2          ; display on, the frame's signal, sprites 16 x 16
main:   ei
frame:  halt                    ; isr: the status kept, the frame counted
woke:   call sends              ; 18  sprites, names queued, the status line
sent:   call run                ; 18  the state's work
ran:    jr frame                ; 13

; run: this frame's routine for the state held in state.
; go: A = a state -> it is the state, and its start routine has run.
;     Both use every register that routine uses (chapter 41)
run:    ld a, (state)           ; 14
        ld hl, frames           ; 11
        jr table                ; 13
go:     ld (state), a           ; 14
        ld hl, starts           ; 11
table:  add a, a                ;  5  two bytes a state
        add a, l                ;  5
        ld l, a                 ;  5  the tables do not cross a page
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5
        jp (hl)                 ;  5  and its RET goes back to the caller

; isr: every frame. The status kept in stat, the signal let down; the frame
; counted. Keeps AF, HL
isr:    push af                 ; 12
        in a, (VDP_CTRL)        ; 12  the status: F, 5S, C, a sprite's number
        ld (stat), a            ; 14
        push hl                 ; 12
        ld hl, (ticks)          ; 17
        inc hl                  ;  7
        ld (ticks), hl          ; 17
        pop hl                  ; 11
        pop af                  ; 11
isrend: ei                      ;  5
        ret                     ; 11

; sends: straight after HALT, before the paper: the copy of the sprites'
; attributes, the names the frame before queued, and the status line's
; digits that changed. Uses A, BC, DE, HL
sends:  VRAM_WRITE SAT          ; 40
        ld hl, copy             ; 11
        ld bc, 21 << 8 | VDP_DATA ; 11  five sprites and the end
        otir                    ; 23 a byte, 18 the last
        ld hl, queued           ; 11
        ld a, (hl)              ;  8
        or a                    ;  5
        jr z, status            ; 13, or 8  none queued
        ld b, a                 ;  5
        ld (hl), 0              ; 11  none from now on
        ld l, low queue         ;  8  the queue in queued's page
.name:  ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12
        inc l                   ;  5
        ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12  its address
        inc l                   ;  5
        ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12  and its name
        inc l                   ;  5
        djnz .name              ; 14, or 9
; status: the score, the best and the lives, what changed (chapter 40)
status: ld hl, score            ; 11
        ld de, SCORE_AT | $4000 ; 11
        call update             ; 18
        ld hl, hi               ; 11
        ld de, HI_AT | $4000    ; 11
        call update             ; 18
        ld a, (lives)           ; 14
        ld hl, shownl           ; 11
        cp (hl)                 ;  8
        ret z                   ; 12, or 6  shown already
        ld (hl), a              ;  8
        ld c, a                 ;  5
        ld a, low LIVES_AT      ;  8
        out (VDP_CTRL), a       ; 12
        ld a, high LIVES_AT | $40 ;  8
        out (VDP_CTRL), a       ; 12
        ld a, c                 ;  5
        or DIGIT0               ;  8  its digit
        out (VDP_DATA), a       ; 12
        ret                     ; 11

; update: HL = a number, three BCD bytes, with a copy of the three last sent
; 256 bytes on; DE = the VRAM address of its first digit, bit 6 set -> each
; byte that differs from its copy sent, and copied. Uses A, BC, DE, HL
update: ld b, 3                 ;  8  three bytes
.byte:  ld a, (hl)              ;  8  a byte of the number
        inc h                   ;  5  the page of the bytes sent
        cp (hl)                 ;  8
        jr z, .same             ; 13, or 8  on the screen already
        ld (hl), a              ;  8  it will be
        ld c, a                 ;  5
        ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12  the address of its first digit
        ld a, c                 ;  5
        call putbcd             ; 18  its two names
.same:  inc e                   ;  5
        inc e                   ;  5  past its two names
        dec h                   ;  5  back to the number
        inc l                   ;  5  and its next byte
        djnz .byte              ; 14, or 9
        ret                     ; 11

; putbcd: A = a BCD byte, the VRAM address set -> its two digits sent, as
; the patterns from DIGIT0 (chapter 40's, with an OR). Uses A, C
putbcd: ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5  the first digit to bits 3 to 0
        and $0F                 ;  8
        or DIGIT0               ;  8  its pattern
        out (VDP_DATA), a       ; 12
        ld a, c                 ;  5
        and $0F                 ;  8  the second digit
        or DIGIT0               ;  8
        out (VDP_DATA), a       ; 12
        ret                     ; 11

; input: the cursor keys and joystick 1 together, with the interrupts off
; (chapters 34 and 35) -> held, in register 14's way: bits 0 to 3 up, down,
; left, right, bit 4 SPACE or button A, a 0 for each held. Uses A, BC, HL
input:  di                      ;  5
        call keys               ; 18  row 8 in register 14's way
        ld c, a                 ;  5
        xor a                   ;  5  port 1
        call joy                ; 18  its register 14
        ei                      ;  5
        and c                   ;  5  held on either
        ld (held), a            ; 14
        ret                     ; 11

; keys: row 8 of the keyboard -> A in register 14's way: the cursor keys as
; the four switches, SPACE as button A, a 0 for each held. The interrupts
; must be off. Uses A, C, HL
keys:   in a, (PPI_C)           ; 12
        and $F0                 ;  8  port C's top bits kept (chapter 34)
        or 8                    ;  8
        out (PPI_C), a          ; 12  row 8
        in a, (PPI_B)           ; 12  bits 7-4: RIGHT DOWN UP LEFT; bit 0: SPACE
        ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $0F                 ;  8
        ld hl, kbdjoy           ; 11
        add a, l                ;  5
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 1                   ;  8  SPACE
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5  into bit 4, button A's
        or (hl)                 ;  8  and the cursor keys as the switches
        or $E0                  ;  8
        ret                     ; 11

; joy: A = $00 for port 1, $40 for port 2 -> A = that port's register 14, a 0
; for each switch closed. Register 15's other seven bits are kept. The
; interrupts must be off. Uses A, B
joy:    ld b, a                 ;  5
        ld a, 15                ;  8
        out (PSG_ADDR), a       ; 12  register 15
        in a, (PSG_READ)        ; 12  as it is
        and $BF                 ;  8  bit 6: the port
        or b                    ;  5
        out (PSG_WRITE), a      ; 12
        ld a, 14                ;  8
        out (PSG_ADDR), a       ; 12  register 14
        in a, (PSG_READ)        ; 12  the port's pins
        ret                     ; 11

; walk: held -> the runner two pixels along X for LEFT or RIGHT, then two
; along Y for UP or DOWN, each where walled finds no wall (chapter 39), so
; that it slides along a wall it meets at a slant. Uses A, BC, DE, HL
walk:   ld bc, (runner)         ; 22  C = Y, B = X
        ld a, (held)            ; 14
        bit 2, a                ; 10  LEFT
        jr nz, .right           ; 13, or 8
        dec b                   ;  5
        dec b                   ;  5  two to the left
.right: bit 3, a                ; 10  RIGHT
        jr nz, .x               ; 13, or 8
        inc b                   ;  5
        inc b                   ;  5  two to the right
.x:     push bc                 ; 12
        call walled             ; 18  NZ: a wall there
        pop bc                  ; 11
        jr nz, .y               ; 13, or 8
        ld a, b                 ;  5
        ld (runner + 1), a      ; 14  the new X
.y:     ld bc, (runner)         ; 22  X as it is now, and Y
        ld a, (held)            ; 14
        bit 0, a                ; 10  UP
        jr nz, .down            ; 13, or 8
        dec c                   ;  5
        dec c                   ;  5  two up
.down:  bit 1, a                ; 10  DOWN
        jr nz, .w               ; 13, or 8
        inc c                   ;  5
        inc c                   ;  5  two down
.w:     push bc                 ; 12
        call walled             ; 18
        pop bc                  ; 11
        ret nz                  ; 12, or 6  a wall
        ld a, c                 ;  5
        ld (runner), a          ; 14  the new Y
        ret                     ; 11

; cell: B = X, C = a line -> HL: the cell of the copy of the names that holds
; the pixel. Keeps BC. Uses A, DE
cell:   ld a, c                 ;  5
        and $F8                 ;  8  the row x 8
        ld l, a                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12
        add hl, hl              ; 12  the row x 32
        ld a, b                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8  the column
        add a, l                ;  5
        ld l, a                 ;  5
        ld de, names            ; 11
        add hl, de              ; 12
        ret                     ; 11

; walled: B = X, C = Y of a ball's place -> NZ if a wall is under any of its
; 16 x 16 pixels: the cells from column X / 8 to (X + 15) / 8 and from row
; (Y + 1) / 8 to (Y + 16) / 8, for a sprite's first line is Y + 1 (chapter
; 26). A wall is the brick's name. Uses A, BC, DE, HL
walled: inc c                   ;  5  the first line
        call cell               ; 18  HL: the cell of the top left pixel
        ld a, b                 ;  5
        and 7                   ;  8
        ld d, 2                 ;  8  two columns on a column's edge,
        jr z, .cols             ; 13, or 8
        inc d                   ;  5  three anywhere else
.cols:  ld a, c                 ;  5
        and 7                   ;  8
        ld e, 2                 ;  8  and two rows, or three
        jr z, .rows             ; 13, or 8
        inc e                   ;  5
.rows:  ld b, d                 ;  5
        push hl                 ; 12
.cell:  ld a, (hl)              ;  8
        cp BRICK                ;  8  the walls' name
        jr z, .wall             ; 13, or 8
        inc hl                  ;  7
        djnz .cell              ; 14, or 9
        pop hl                  ; 11
        ld bc, 32               ; 11
        add hl, bc              ; 12  the row of cells below
        dec e                   ;  5
        jr nz, .rows            ; 13, or 8
        ret                     ; 11  Z: no wall
.wall:  pop hl                  ; 11
        or a                    ;  5  A is BRICK
        ret                     ; 11  NZ: a wall

; patrol: IX = a face's attributes in the copy, HL = its step -> X a step
; on; a step that would take it outside X_MIN to X_MAX, the walls' inside,
; turns it, and it steps the other way instead. Uses A
patrol: ld a, (ix + 1)          ; 21  X
        add a, (hl)             ;  8  and its step
        sub X_MIN               ;  8
        cp X_MAX - X_MIN + 1    ;  8  carry from X_MIN to X_MAX
        jr c, .x                ; 13, or 8
        ld a, (hl)              ;  8
        neg                     ; 10
        ld (hl), a              ;  8  the other way
        add a, (ix + 1)         ; 21
        sub X_MIN               ;  8
.x:     add a, X_MIN            ;  8
        ld (ix + 1), a          ; 21
        ret                     ; 11

; step: a frame of the play: the runner, then each face. Uses A, BC, DE,
; HL, IX
step:   call walk               ; 18
        ld ix, faces            ; 16
        ld hl, steps            ; 11
        ld de, 4                ; 11
        ld b, 4                 ;  8  four faces
.face:  call patrol             ; 18
        add ix, de              ; 17  the next face's attributes
        inc l                   ;  5  and its step
        djnz .face              ; 14, or 9
        ret                     ; 11

; pick: the cells under the runner's 16 x 16 pixels, as walled finds them ->
; each with a gem taken by took. Uses A, BC, DE, HL
pick:   ld bc, (runner)         ; 22  C = Y, B = X
        inc c                   ;  5  the first line
        call cell               ; 18  HL: the cell of the top left pixel
        ld a, b                 ;  5
        and 7                   ;  8
        ld d, 2                 ;  8  two columns on a column's edge,
        jr z, .cols             ; 13, or 8
        inc d                   ;  5  three anywhere else
.cols:  ld a, c                 ;  5
        and 7                   ;  8
        ld e, 2                 ;  8  and two rows, or three
        jr z, .rows             ; 13, or 8
        inc e                   ;  5
.rows:  ld b, d                 ;  5
        push hl                 ; 12
.cell:  ld a, (hl)              ;  8
        cp GEM                  ;  8
        call z, took            ; 18, or 11  a gem
        inc hl                  ;  7
        djnz .cell              ; 14, or 9
        pop hl                  ; 11
        ld bc, 32               ; 11
        add hl, bc              ; 12  the row of cells below
        dec e                   ;  5
        jr nz, .rows            ; 13, or 8
        ret                     ; 11

; took: HL = a gem's cell in the copy of the names -> the cell paper again,
; queued; ten points; a gem fewer. Keeps BC, DE, HL. Uses A
took:   push bc                 ; 12
        push de                 ; 12
        push hl                 ; 12
        xor a                   ;  5  PAPER
        call post               ; 18
        ld a, POINTS            ;  8
        call addsc              ; 18
        ld hl, gems             ; 11
        dec (hl)                ; 12  a gem fewer
        pop hl                  ; 11
        pop de                  ; 11
        pop bc                  ; 11
        ret                     ; 11

; post: HL = a cell of the copy of the names, A = a name -> the name written
; there and queued for the next frame's sends. Uses A, BC, DE, HL
post:   ld (hl), a              ;  8
        ld c, a                 ;  5  the name
        ld de, ($1800 + $4000 - names) & $FFFF ; 11
        add hl, de              ; 12  its VRAM address, plus $4000 for writing
        ex de, hl               ;  5  in DE
        ld hl, queued           ; 11
        ld a, (hl)              ;  8
        inc (hl)                ; 12  one more
        ld b, a                 ;  5
        add a, a                ;  5
        add a, b                ;  5  three bytes each
        add a, low queue        ;  8
        ld l, a                 ;  5  the queue in queued's page
        ld (hl), e              ;  8
        inc l                   ;  5
        ld (hl), d              ;  8
        inc l                   ;  5
        ld (hl), c              ;  8
        ret                     ; 11

; sow: a gem in a free cell of a corridor: one of its eight rows and a
; column from 1 to 30, chosen by random, again while the cell is a wall, is
; not paper, or lies under the runner or where a step takes it: its 3 x 3
; cells and one more all round. Uses A, BC, DE, HL
sow:    call random             ; 18
        and 7                   ;  8  one of the eight rows
        ld e, a                 ;  5
        ld d, 0                 ;  8
        ld hl, rows             ; 11
        add hl, de              ; 12
        ld c, (hl)              ;  8  C: the row
        call random             ; 18
        and 31                  ;  8  the column
        jr z, sow               ; 13, or 8  0, the left wall: again
        cp 31                   ;  8
        jr z, sow               ; 13, or 8  31, the right wall
        ld b, a                 ;  5  B: the column
        ld a, (runner)          ; 14  the runner's Y
        inc a                   ;  5  its first line
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 31                  ;  8  its first row
        ld e, a                 ;  5
        ld a, c                 ;  5
        sub e                   ;  5
        inc a                   ;  5  from the row above its first
        cp 5                    ;  8  carry: one of those five rows
        jr nc, .free            ; 13, or 8
        ld a, (runner + 1)      ; 14  its X
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 31                  ;  8  its first column
        ld e, a                 ;  5
        ld a, b                 ;  5
        sub e                   ;  5
        inc a                   ;  5
        cp 5                    ;  8
        jr c, sow               ; 13, or 8  near the runner: again
.free:  ld l, c                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12  the row x 32
        ld a, l                 ;  5
        or b                    ;  5  and the column
        ld l, a                 ;  5
        ld de, names            ; 11
        add hl, de              ; 12  HL: the cell in the copy
        ld a, (hl)              ;  8
        cp PAPER                ;  8
        jr nz, sow              ; 13, or 8  a gem there already: again
        ld a, GEM               ;  8
        jp post                 ; 11  the gem, queued

; round: GEMS gems sown, and as many to take. Uses A, BC, DE, HL
round:  ld b, GEMS              ;  8
.gem:   push bc                 ; 12
        call sow                ; 18
        pop bc                  ; 11
        djnz .gem               ; 14, or 9
        ld a, GEMS              ;  8
        ld (gems), a            ; 14
        ret                     ; 11

; play0: no frame counted yet
play0:  ld a, (ticks)           ; 14
        ld (last), a            ; 14
        ret                     ; 11

; play1: THE FRAME OF THE PLAY. The keys; eight gems more when the last is
; gone; a step of the runner and of every face for each frame counted
; (chapter 33); the gems under the runner; the best score; and a touch: C,
; which isr kept from the frame just drawn, where only the runner can meet a
; face. Uses every register but IY
play1:  call input              ; 18  held, first, while the frame is young
        ld a, (gems)            ; 14
        or a                    ;  5
        call z, round           ; 18, or 11  the last gem gone: eight more
        ld hl, last             ; 11
        ld a, (ticks)           ; 14
        ld b, a                 ;  5
        sub (hl)                ;  8  the frames gone by
        ld (hl), b              ;  8  and ticks, for the next time
        ld b, a                 ;  5
.step:  push bc                 ; 12
        call step               ; 18  the runner and the faces
        pop bc                  ; 11
        djnz .step              ; 14, or 9
        call pick               ; 18  its gems
        call best               ; 18  hi kept the best
        ld hl, stale            ; 11
        ld a, (hl)              ;  8
        or a                    ;  5
        jr z, .look             ; 13, or 8
        dec (hl)                ; 12  a frame whose C is not believed
        ret                     ; 11
.look:  ld a, (stat)            ; 14
        and $20                 ;  8  C
        ret z                   ; 12, or 6  no sprites met
touch:  ld a, HIT               ;  8
        jp go                   ; 11  a face touched the runner

; hit0: a life fewer, and the game held still
hit0:   ld hl, lives            ; 11
        dec (hl)                ; 12  the status line shows it next frame
        ld a, HOLD              ;  8
        ld (left), a            ; 14
        ret                     ; 11

; hit1: at the end of the wait, GAME OVER, or the runner home again
hit1:   ld hl, left             ; 11
        dec (hl)                ; 12
        ret nz                  ; 12, or 6
        ld a, (lives)           ; 14
        or a                    ;  5
        ld a, OVER              ;  8
        jp z, go                ; 11  no lives left
        ld hl, HOME_X << 8 | HOME_Y ; 11
        ld (runner), hl         ; 17  home again, Y and X
home:   ld a, PLAY              ;  8
        jp go                   ; 11

; title0: the title on a clear screen, with the runner and a face
title0: call wipe
        ld hl, ttext            ; the title's lines, each its address and text
        ld b, 4
.line:  push bc
        ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        di
        call say                ; HL to the line's 0
        ei
        inc hl
        pop bc
        djnz .line
        ld hl, tcopy            ; the two sprites
        ld de, copy
        ld bc, 9
        ldir
        ret

; title1: SPACE or button A held? The seed is the frame count, 1 for 0
; (chapter 41), and a game begins
title1: call input              ; held
        and $10                 ; SPACE, button A
        ret nz
        ld hl, (ticks)          ; the seed
        ld a, h
        or l
        jr nz, .seed
        inc hl
.seed:  ld (seed), hl
pressed: call setup             ; the arena, the status line, the sprites
        call round              ; the first round's gems
        ld a, PLAY
        jp go

; over0: GAME OVER, and WAITS frames of it
over0:  ld hl, otext
        ld de, $1800 + 32 * 4 + 11 | $4000
        di
        call say
        ei
        ld a, WAITS
        ld (left), a
        ret

; over1: at the end of the wait, the title again
over1:  ld hl, left
        dec (hl)
        ret nz
again:  ld a, TITLE
        jp go

; setup: a new game. The arena into the copy of the names and to the VDP;
; score 0, none of its digits shown; three lives; the sprites at their
; first places, the faces' steps; no names queued
setup:  call arena
        ld hl, score
        ld b, 3
.zero:  ld (hl), 0
        inc l
        djnz .zero
        ld hl, shown
        ld b, 6
.none:  ld (hl), $FF            ; none of its digits shown: the sends send all
        inc l
        djnz .none
        ld a, LIVES
        ld (lives), a
        ld a, $FF
        ld (shownl), a
        ld hl, first            ; the sprites' first places
        ld de, copy
        ld bc, 21
        ldir
        ld hl, fsteps           ; and the faces' steps
        ld de, steps
        ld bc, 4
        ldir
        xor a
        ld (queued), a
        ld (stale), a
        ret

; arena: the names of the play, from the table arena's rows, into the copy
; of the names and to the VDP at once, 41 T-states a name in its rows: row
; 0 the status line's labels, rows 1 to 23 a wall, 30 names, a wall
arena:  di                      ;  5
        VRAM_WRITE $1800        ; 40
        ei                      ;  5
        ld hl, row0             ; 11  row 0
        ld de, names            ; 11
        ld b, 32                ;  8
.top:   ld a, (hl)              ;  8
        ld (de), a              ;  8
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        inc de                  ;  7
        djnz .top               ; 14, or 9
        ex de, hl               ;  5  HL: the copy's row 1
        ld de, arows            ; 11  DE: the table
        ld c, 23                ;  8  rows 1 to 23
.row:   ld a, (de)              ;  8  the row's middle name
        inc de                  ;  7
        push af                 ; 12
        ld a, BRICK             ;  8
        ld (hl), a              ;  8
        inc hl                  ;  7
        out (VDP_DATA), a       ; 12  the wall on the left
        pop af                  ; 11
        ld b, 30                ;  8
.mid:   ld (hl), a              ;  8
        inc hl                  ;  7
        out (VDP_DATA), a       ; 12
        djnz .mid               ; 14, or 9: 41 T-states a name
        ld a, BRICK             ;  8
        ld (hl), a              ;  8
        inc hl                  ;  7
        out (VDP_DATA), a       ; 12  and on the right
        dec c                   ;  5
        jr nz, .row             ; 13, or 8
        ret                     ; 11

; wipe: the 768 names spaces (chapter 41). Uses A, BC
wipe:   di
        VRAM_WRITE $1800
        ei
        ld bc, 768
.sp:    ld a, 32
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .sp
        ret

; best: score against hi, the first digits first -> hi is score when score
; is higher. Uses A, BC, DE, HL
best:   ld hl, score            ; 11
        ld de, hi               ; 11
        ld b, 3                 ;  8  three bytes
.byte:  ld a, (de)              ;  8  a byte of hi
        cp (hl)                 ;  8  less the same byte of score
        jr c, .new              ; 13, or 8  score's is higher: a new best
        ret nz                  ; 12, or 6  hi's is higher
        inc l                   ;  5
        inc e                   ;  5  the same: the next byte decides
        djnz .byte              ; 14, or 9
        ret                     ; 11  the same number
.new:   ld c, b                 ;  5  the bytes from here on, this one too;
        ld b, 0                 ;  8  the ones before are the same
        ldir                    ; 23, and 18 the last time
        ret                     ; 11

; addsc: A = points, two BCD digits -> added to score, the carry taken into
; the digits before with ADC and DAA (chapter 9). Uses A, HL
addsc:  ld hl, score + 2        ; 11  the last two digits
        add a, (hl)             ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5  DEC L leaves the carry alone
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        ret                     ; 11

; say: HL = a text ending in a 0 byte, DE = the VRAM address of its first
; character, bit 6 set -> the text sent, HL on its 0. Uses A, HL
say:    ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12  the address of the first character
.char:  ld a, (hl)              ;  8  the next character
        or a                    ;  5
        ret z                   ; 12, or 6  the 0: the end
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        jr .char                ; 13

; random: the next of the 65,535 states of a 16-bit xorshift, x XOR x << 7,
; XOR x >> 9, XOR x << 8 -> seed, A = its high byte. Uses A, HL
random: ld hl, (seed)           ; 17
        ld a, h                 ;  5
        rra                     ;  5  bit 0 of H into the carry
        ld a, l                 ;  5
        rra                     ;  5  x << 7's high byte: that bit and L >> 1
        xor h                   ;  5
        ld h, a                 ;  5  H XOR it
        ld a, l                 ;  5
        rrca                    ;  5
        and $80                 ;  8  x << 7's low byte: L's bit 0 at bit 7
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x << 7
        ld a, h                 ;  5
        srl a                   ; 10  x >> 9, which is H >> 1
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x >> 9, which changes L alone
        xor h                   ;  5
        ld h, a                 ;  5  x XOR x << 8: H XOR L
        ld (seed), hl           ; 17
        ret                     ; 11
        ALIGN 16
starts: dw title0, play0, hit0, over0 ; each state's first frame
frames: dw title1, play1, hit1, over1 ; and every frame of it
tiles:                          ; paper, brick (chapter 39), alley, gem
        db $00, $00, $00, $00, $00, $00, $00, $00
        db $FF, $80, $80, $80, $FF, $08, $08, $08
        db $00, $00, $00, $00, $00, $00, $00, $00
        db $18, $3C, $7E, $FF, $7E, $3C, $18, $00
tcols:                          ; their colours
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $14, $14, $14, $14, $14, $14, $14, $14
