        db $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F
row0:                           ; the status line's labels
        db $20, $53, $43, $4F, $52, $45, $20, $20, $20, $20, $20, $20, $20, $20, $4C, $49
        db $56, $45, $53, $20, $20, $20, $20, $48, $49, $20, $20, $20, $20, $20, $20, $20
arows:                          ; rows 1 to 23: the name between the walls
        db $01, $00, $00, $00, $00, $00, $02, $02, $00, $00, $02, $02, $00, $00, $02, $02, $00, $00, $02, $02, $00, $00, $01
rows:                           ; the corridors' rows, where sow puts gems
        db $09, $0A, $0D, $0E, $11, $12, $15, $16
first:                          ; the sprites' attributes when a game begins
        db $17, $78, $00, $01
        db $37, $28, $04, $04
        db $57, $C0, $04, $04
        db $77, $60, $04, $04
        db $97, $A8, $04, $04
