fsteps:                         ; the faces' steps
        db $01, $FE, $02, $FF
tcopy:                          ; the title's runner and face, and the end
        db $2B, $38, $00, $01, $2B, $B8, $04, $04
        db $D0
nums:                           ; score and the best score at the start
        db $00, $00, $00, $00, $01, $00
ttext:                          ; the title's lines, each its address and text
        dw $1800 + 32 * 6 + 11 | $4000
        db "GRIN ALLEY", 0
        dw $1800 + 32 * 15 + 10 | $4000
        db "PRESS SPACE", 0
        dw $1800 + 32 * 18 + 10 | $4000
        db "CURSOR KEYS", 0
        dw $1800 + 32 * 19 + 9 | $4000
        db "OR JOYSTICK 1", 0
otext:  db "GAME OVER", 0
sprites:                        ; the runner and a face, 16 x 16 (chapter 26)
